//! Opt-in native playback acceptance with generated bytes and a loopback-only authenticated origin.
use crate::{
    home_gateway::HomeGateway, media::ResolvedTarget, player::Player, player_protocol::Command,
    services::ServerSession, torrentio,
};
use axum::{
    Router,
    body::Body,
    extract::State,
    http::{HeaderMap, Method, StatusCode},
    response::Response,
    routing::{get, post},
};
use serde_json::json;
use std::{rc::Rc, sync::Arc};
const FILE: &str = "a3000000-0000-4000-8000-000000000001";
const WORK: &str = "a1000000-0000-4000-8000-000000000001";
const PART: &str = "a2000000-0000-4000-8000-000000000001";
pub struct Fixture(tokio::task::JoinHandle<()>);
impl Drop for Fixture {
    fn drop(&mut self) {
        self.0.abort();
    }
}
async fn content(
    State(bytes): State<Arc<Vec<u8>>>,
    headers: HeaderMap,
    method: Method,
) -> Response {
    if headers.get("authorization").and_then(|v| v.to_str().ok())
        != Some("Bearer fixture-home-token")
    {
        return Response::builder()
            .status(StatusCode::UNAUTHORIZED)
            .body(Body::empty())
            .unwrap();
    }
    let range = headers.get("range").and_then(|v| v.to_str().ok());
    let selected = range
        .and_then(|v| v.strip_prefix("bytes="))
        .and_then(|v| v.split_once('-'))
        .and_then(|(start, end)| {
            Some((
                start.parse::<usize>().ok()?,
                if end.is_empty() {
                    bytes.len() - 1
                } else {
                    end.parse::<usize>().ok()?.min(bytes.len() - 1)
                },
            ))
        });
    let (start, end) = selected.unwrap_or((0, bytes.len() - 1));
    if (range.is_some() && selected.is_none()) || start > end || end >= bytes.len() {
        return Response::builder()
            .status(StatusCode::RANGE_NOT_SATISFIABLE)
            .header("content-range", format!("bytes */{}", bytes.len()))
            .body(Body::empty())
            .unwrap();
    }
    let mut response = Response::builder()
        .status(if range.is_some() {
            StatusCode::PARTIAL_CONTENT
        } else {
            StatusCode::OK
        })
        .header("accept-ranges", "bytes")
        .header("content-length", end - start + 1)
        .header("content-type", "video/x-matroska");
    if range.is_some() {
        response = response.header(
            "content-range",
            format!("bytes {start}-{end}/{}", bytes.len()),
        );
    }
    response
        .body(if method == Method::HEAD {
            Body::empty()
        } else {
            Body::from(bytes[start..=end].to_vec())
        })
        .unwrap()
}
pub async fn install(
    player: &Rc<Player>,
    runtime: Arc<tokio::runtime::Runtime>,
) -> Result<Fixture, String> {
    let path = std::env::var_os("NAHHASIO_PLAY_FILE").ok_or("Generated local fixture required")?;
    let (fixture,gateway)=runtime.spawn(async move {
        let bytes=tokio::fs::read(path).await.map_err(|_|"Cannot read generated video")?;
        if bytes.is_empty() || bytes.len()>32*1024*1024 {return Err("Generated fixture must be 1 byte to 32 MiB");}
        let app=Router::new().route("/api/v1/media/{id}/content",get(content))
            .route("/api/v1/auth/login",post(||async {axum::Json(json!({"token":"fixture-home-token","expiresAt":"2099-01-01T00:00:00Z","user":{"id":"fixture","accountId":WORK,"name":"Fixture","email":"fixture@example.invalid","role":"member","kind":"member","avatarKey":"cars-1.png","bio":"","isAdmin":false,"updatedAt":"2026-11-05T00:00:00Z"}}))})).with_state(Arc::new(bytes));
        let listener=tokio::net::TcpListener::bind("127.0.0.1:0").await.map_err(|_|"Cannot bind fixture origin")?;
        let origin=format!("http://{}/",listener.local_addr().map_err(|_|"Cannot inspect fixture origin")?);
        let fixture=Fixture(tokio::spawn(async move {let _=axum::serve(listener,app).await;}));
        let transport=ServerSession::new(&origin).map_err(|_|"Cannot prepare fixture transport")?;
        transport.execute(crate::bridge::Request{id:"home-smoke".into(),command:"login".into(),payload:json!({"email":"fixture@example.invalid","password":"fixture-only"})}).await.map_err(|_|"Cannot authenticate fixture transport")?;
        let gateway=HomeGateway::start(transport,FILE.into()).await.map_err(|_|"Cannot start native media gateway")?;
        let client=reqwest::Client::builder().no_proxy().timeout(std::time::Duration::from_secs(5)).build().map_err(|_|"Cannot prepare fixture reader")?;
        let blocked=client.get(gateway.endpoint()).header("origin","nahhasio://app").send().await.map_err(|_|"Cannot inspect gateway origin guard")?;
        if blocked.status()!=reqwest::StatusCode::FORBIDDEN {return Err("Gateway admitted a browser origin");}
        let head=client.head(gateway.endpoint()).send().await.map_err(|_|"Cannot inspect gateway HEAD")?;
        if head.status()!=reqwest::StatusCode::OK {return Err("Gateway HEAD failed");}
        let range=client.get(gateway.endpoint()).header("range","bytes=0-31").send().await.map_err(|_|"Cannot inspect gateway range")?;
        if range.status()!=reqwest::StatusCode::PARTIAL_CONTENT || range.bytes().await.map_err(|_|"Cannot read gateway range")?.len()!=32 {return Err("Gateway range failed");}
        Ok((fixture,gateway))
    }).await.map_err(|_|"Home playback fixture task failed")?.map_err(str::to_owned)?;
    let title = "Native home-library diagnostic".to_owned();
    player
        .execute(Command::Preview {
            title: title.clone(),
        })
        .await
        .map_err(|e| e.message)?;
    let session = player
        .snapshot()
        .session_id
        .ok_or("Missing native playback session")?;
    player
        .play_home(
            &session,
            ResolvedTarget {
                work_id: WORK.into(),
                installment_id: PART.into(),
                episode_id: None,
                poster_id: None,
                work_title: title.clone(),
                title,
                search: torrentio::Search {
                    imdb_id: String::new(),
                    kind: torrentio::Kind::Movie,
                    season: None,
                    episode: None,
                },
            },
            gateway,
        )
        .map_err(|e| e.message)?;
    Ok(fixture)
}
